contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint v, uint w) public payable {
        bool r1;
        c.SetMinSum(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = true; } else { r1 = false; }
        bool r2;
        c.SetMinSum(w); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = true; } else { r2 = false; }
        uint minSumAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(!r1 && !r2 && minSumAfter == w);
    }

    receive() external payable {}
}

